							</div>
							<div class="mt-5 flex items-center gap-3">
								<button
									type="button"
									class="w-full rounded-full border border-ui-line-gray-300 py-3.5 text-xs font-semibold text-ui-ink-gray-700 transition active:scale-[0.98]"
									@click="filterDraft.jenis = []"
								>
									Reset
								</button>
								<button
									type="button"
									class="w-full rounded-full bg-primary py-3.5 text-xs font-semibold text-ui-onPrimary shadow-sm transition active:scale-[0.98]"
									@click="showJenisSheet = false"
								>
									Selesai
								</button>
							</div>
						</div>
					</Transition>
				</div>
			</Transition>
		</Teleport>

		<!-- ====== Sub-sheet STATUS (pilih banyak) ====== -->
		<Teleport to="body">
			<Transition
				enter-active-class="transition-opacity duration-200"
				enter-from-class="opacity-0"
				leave-active-class="transition-opacity duration-150"
				leave-to-class="opacity-0"
			>
				<div
					v-if="showStatusSheet"
					class="fixed inset-0 z-[80] flex items-end justify-center bg-black/40"
					@click.self="showStatusSheet = false"
				>
					<Transition
						appear
						enter-active-class="transition-transform duration-200 ease-out"
						enter-from-class="translate-y-full"
						leave-active-class="transition-transform duration-150 ease-in"
						leave-to-class="translate-y-full"
					>
						<div
							v-if="showStatusSheet"
							class="dp-pop text-xs w-full max-w-screen-sm rounded-t-3xl bg-ui-surface px-5 pb-[max(1.25rem,env(safe-area-inset-bottom))] pt-3 shadow-2xl"
						>
							<div
								class="mx-auto mb-4 h-1.5 w-10 rounded-full bg-ui-surface-gray-300"
							/>
							<h2 class="text-center text-base font-semibold text-ui-ink-gray-900">
								Pilih Status
							</h2>
							<p class="mb-4 mt-1 text-center text-xs text-ui-ink-gray-400">
								Bisa pilih lebih dari satu
							</p>

							<div class="max-h-[55vh] space-y-2 overflow-y-auto px-0.5">
								<button
									v-for="s in STATUS_LIST"
									:key="s"
									type="button"
									class="flex w-full cursor-pointer items-center justify-between gap-2 rounded-2xl border px-4 py-3.5 text-left transition"
									:class="
										filterDraft.status.includes(s)
											? 'border-primary bg-primary/5'
											: 'border-ui-line-gray-200'
									"
									@click="toggleStatusDraft(s)"
								>
									<span class="flex min-w-0 items-center gap-2.5">
										<span
											class="h-2.5 w-2.5 shrink-0 rounded-full border-2"
											:class="statusDotClass(s)"
										/>
										<span
											class="truncate text-xs font-medium text-ui-ink-gray-800"
											>{{ s }}</span
										>
									</span>
									<span
										class="flex h-5 w-5 shrink-0 items-center justify-center rounded-md border-2 transition"
										:class="
											filterDraft.status.includes(s)
												? 'border-primary bg-primary text-ui-onPrimary'
												: 'border-ui-line-gray-300'
										"
									>
										<svg
											v-if="filterDraft.status.includes(s)"
											xmlns="http://www.w3.org/2000/svg"
											viewBox="0 0 24 24"
											class="h-3.5 w-3.5"
											fill="none"
											stroke="currentColor"
											stroke-width="3"
											stroke-linecap="round"
											stroke-linejoin="round"
										>
											<path d="M20 6 9 17l-5-5" />
										</svg>
									</span>
								</button>
							</div>

							<div class="mt-5 flex items-center gap-3">
								<button
									type="button"
									class="w-full rounded-full border border-ui-line-gray-300 py-3.5 text-xs font-semibold text-ui-ink-gray-700 transition active:scale-[0.98]"
									@click="filterDraft.status = []"
								>
									Reset
								</button>
								<button
									type="button"
									class="w-full rounded-full bg-primary py-3.5 text-xs font-semibold text-ui-onPrimary shadow-sm transition active:scale-[0.98]"
									@click="showStatusSheet = false"
								>
									Selesai
								</button>
							</div>
						</div>
					</Transition>
				</div>
			</Transition>
		</Teleport>

		<!-- ====== Sub-sheet KALENDER rentang Tanggal Request ====== -->
		<Teleport to="body">
			<Transition
				enter-active-class="transition-opacity duration-200"
				enter-from-class="opacity-0"
				leave-active-class="transition-opacity duration-150"
				leave-to-class="opacity-0"
			>
				<div
					v-if="showDateSheet"
					class="fixed inset-0 z-[80] flex items-end justify-center bg-black/40"
					@click.self="showDateSheet = false"
				>
					<Transition
						appear
						enter-active-class="transition-transform duration-200 ease-out"
						enter-from-class="translate-y-full"
						leave-active-class="transition-transform duration-150 ease-in"
						leave-to-class="translate-y-full"
					>
						<div
							v-if="showDateSheet"
							class="dp-pop text-xs w-full max-w-screen-sm rounded-t-3xl bg-ui-surface px-5 pb-[max(1.25rem,env(safe-area-inset-bottom))] pt-3 shadow-2xl"
						>
							<div
								class="mx-auto mb-4 h-1.5 w-10 rounded-full bg-ui-surface-gray-300"
							/>
							<h2 class="text-center text-base font-semibold text-ui-ink-gray-900">
								Tanggal Request
							</h2>
							<p class="mb-3 mt-1 text-center text-xs text-ui-ink-gray-400">
								Pilih tanggal mulai lalu tanggal akhir
							</p>

							<div class="mb-2 flex items-center justify-between px-1">
								<button
									type="button"
									class="flex h-9 w-9 items-center justify-center rounded-full text-ui-ink-gray-600 hover:bg-ui-surface-gray-100"
									aria-label="Bulan sebelumnya"
									@click="prevMonth"
								>
									<svg
										xmlns="http://www.w3.org/2000/svg"
										viewBox="0 0 24 24"
										class="h-5 w-5"
										fill="none"
										stroke="currentColor"
										stroke-width="2"
										stroke-linecap="round"
										stroke-linejoin="round"
									>
										<path d="m15 18-6-6 6-6" />
									</svg>
								</button>
								<span class="text-xs font-semibold text-ui-ink-gray-900">{{
									calLabel
								}}</span>
								<button
									type="button"
									class="flex h-9 w-9 items-center justify-center rounded-full text-ui-ink-gray-600 hover:bg-ui-surface-gray-100"
									aria-label="Bulan berikutnya"
									@click="nextMonth"
								>
									<svg
										xmlns="http://www.w3.org/2000/svg"
										viewBox="0 0 24 24"
										class="h-5 w-5"
										fill="none"
										stroke="currentColor"
										stroke-width="2"
										stroke-linecap="round"
										stroke-linejoin="round"
									>
										<path d="m9 18 6-6-6-6" />
									</svg>
								</button>
							</div>

							<div class="grid grid-cols-7 gap-y-1 text-center">
								<div
									v-for="w in WEEKDAYS"
									:key="w"
									class="py-1.5 text-xs font-semibold text-ui-ink-gray-400"
								>
									{{ w }}
								</div>
								<div v-for="(cell, i) in calDays" :key="i" class="py-0.5">
									<button
										v-if="cell"
										type="button"
										class="mx-auto flex h-9 w-9 items-center justify-center text-xs transition"
										:class="dayClass(cell)"
										@click="pickDay(cell)"
									>
										{{ cell.getDate() }}
									</button>
								</div>
							</div>

							<div class="mt-3 flex items-center justify-center gap-2 text-xs">
								<span
									class="rounded-lg bg-ui-surface-gray-100 px-3 py-1.5 font-medium"
									:class="
										rangeStart
											? 'text-ui-ink-gray-800'
											: 'text-ui-ink-gray-400'
									"
								>
									{{ rangeStart ? formatDate(rangeStart) : 'Mulai' }}
								</span>
								<span class="text-ui-ink-gray-400">→</span>
								<span
									class="rounded-lg bg-ui-surface-gray-100 px-3 py-1.5 font-medium"
									:class="
										rangeEnd ? 'text-ui-ink-gray-800' : 'text-ui-ink-gray-400'
									"
								>
									{{ rangeEnd ? formatDate(rangeEnd) : 'Akhir' }}
								</span>
							</div>

							<div class="mt-5 flex items-center gap-3">
								<button
									type="button"
									class="w-full rounded-full border border-ui-line-gray-300 py-3.5 text-xs font-semibold text-ui-ink-gray-700 transition active:scale-[0.98]"
									@click="clearDateRange"
								>
									Reset
								</button>
								<button
									type="button"
									class="w-full rounded-full bg-primary py-3.5 text-xs font-semibold text-ui-onPrimary shadow-sm transition active:scale-[0.98]"
									@click="applyDateRange"
								>
									Terapkan
								</button>
							</div>
						</div>
					</Transition>
				</div>
			</Transition>
		</Teleport>
	</div>
</template>

<script setup>
import { computed, onMounted, reactive, ref } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import { statusPillClass, statusDotClass, STATUS_OPTIONS } from '../data/requestDokCollStatus'
import { createResource } from 'frappe-ui'
import { currentUser, loadMyRoles } from '../data/user'
import { useListPersistence } from '../composables/useListPersistence'

const router = useRouter()
const route = useRoute()
const listPersistence = useListPersistence('RequestDokumenCollection')

// Tile Home "Request BSTK" (MO) / "Request TTS" (Manager Finance) membuka halaman
// ini dengan ?jenis=. Jenisnya dikunci: filter jenis disembunyikan dan daftar
// hanya memuat jenis itu. Dibawa ke detail supaya tombol kembali tetap terkunci.
const jenisTerkunci = computed(() =>
	['TTS', 'BSTK'].includes(route.query.jenis) ? route.query.jenis : null
)
const judul = computed(() =>
	jenisTerkunci.value ? `Request ${jenisTerkunci.value}` : 'Request Dokumen Collection'
)

function goToDetail(name) {
	router.push({
		name: 'RequestDokumenCollectionDetail',
		params: { name },
		query: jenisTerkunci.value ? { jenis: jenisTerkunci.value } : undefined,
	})
}

// FAB "Tambah" hanya untuk role yang punya izin create di doctype (System Manager,
// Admin Coll, Head Admin Coll; Administrator memiliki semua role).
const CREATE_ROLES = ['System Manager', 'Admin Coll', 'Head Admin Coll']
const canCreate = computed(
	() =>
		currentUser.user === 'Administrator' ||
		CREATE_ROLES.some((r) => (currentUser.roles || []).includes(r))
)
function onCreate() {
	router.push({ name: 'RequestDokumenCollectionCreate' })
}

const FIELDS = [
	'name',
	'status',
	'jenis_dokumen',
	'cabang_collection',
	'tanggal',
	'requested_by',
	'jumlah_buku',
	'jumlah_nomor',
	'nomor_awal',
	'nomor_akhir',
]
const PAGE_LENGTH = 20

const STATUS_LIST = STATUS_OPTIONS
const JENIS_LIST = ['TTS', 'BSTK']

const rows = ref([])
const start = ref(0)
const hasMore = ref(false)
const loading = ref(false)
const error = ref('')

// Rentang nomor untuk TTS (nomor_awal – nomor_akhir).
function nomorRange(row) {
	const a = row.nomor_awal
	const b = row.nomor_akhir
	if (a && b) return `${a} – ${b}`
	if (a) return String(a)
	return '—'
}

// ---- Sort -----------------------------------------------------------------
const sortField = ref('modified')
const sortDir = ref('desc')
const SORT_FIELDS = [
	{ key: 'modified', label: 'Terakhir Diubah' },
	{ key: 'creation', label: 'Dibuat' },
	{ key: 'name', label: 'ID' },
	{ key: 'tanggal', label: 'Tanggal Request' },
	{ key: 'jenis_dokumen', label: 'Jenis Dokumen' },
	{ key: 'status', label: 'Status' },
	{ key: 'jumlah_buku', label: 'Jumlah Buku' },
]

const showSortSheet = ref(false)
const sortFieldDraft = ref(sortField.value)
const sortDirDraft = ref(sortDir.value)
function openSort() {
	sortFieldDraft.value = sortField.value
	sortDirDraft.value = sortDir.value
	showSortSheet.value = true
}
function toggleSortDirDraft() {
	sortDirDraft.value = sortDirDraft.value === 'asc' ? 'desc' : 'asc'
}
function applySort() {
	sortField.value = sortFieldDraft.value
	sortDir.value = sortDirDraft.value
	listPersistence.writePreferences({ sortField: sortField.value, sortDir: sortDir.value })
	showSortSheet.value = false
	reload()
}

// ---- Filter ---------------------------------------------------------------
function blankFilter() {
	return {
		name: '',
		jenis: [],
		status: [],
		tanggal_dari: '',
		tanggal_sampai: '',
	}
}
const filterDraft = reactive(blankFilter())
const appliedFilter = reactive(blankFilter())

const showFilterSheet = ref(false)
const showStatusSheet = ref(false)
const showJenisSheet = ref(false)

function openFilter() {
	Object.assign(filterDraft, {
		...appliedFilter,
		jenis: [...appliedFilter.jenis],
		status: [...appliedFilter.status],
	})
	showFilterSheet.value = true
}
function toggleStatusDraft(s) {
	const i = filterDraft.status.indexOf(s)
	if (i === -1) filterDraft.status.push(s)
	else filterDraft.status.splice(i, 1)
}
function toggleJenisDraft(j) {
	const i = filterDraft.jenis.indexOf(j)
	if (i === -1) filterDraft.jenis.push(j)
	else filterDraft.jenis.splice(i, 1)
}
function summarize(arr) {
	if (!arr.length) return ''
	if (arr.length === 1) return arr[0]
	return `${arr[0]} +${arr.length - 1}`
}
const statusSummary = computed(() => summarize(filterDraft.status))
const jenisSummary = computed(() => summarize(filterDraft.jenis))

const activeFilterCount = computed(() => {
	const f = appliedFilter
	let n = 0
	if (f.name.trim()) n++
	if (!jenisTerkunci.value && f.jenis.length) n++
	if (f.status.length) n++
	if (f.tanggal_dari || f.tanggal_sampai) n++
	return n
})

function applyFilter() {
	Object.assign(appliedFilter, {
		...filterDraft,
		jenis: [...filterDraft.jenis],
		status: [...filterDraft.status],
	})
	listPersistence.writeSession({ filters: appliedFilter })
	showFilterSheet.value = false
	reload()
}
function clearFilter() {
	Object.assign(filterDraft, blankFilter())
	Object.assign(appliedFilter, blankFilter())
	listPersistence.clearSession()
	showFilterSheet.value = false
	reload()
}

// ---- Kalender rentang Tanggal Request -------------------------------------
const showDateSheet = ref(false)
const calCursor = ref(new Date())
const rangeStart = ref('')
const rangeEnd = ref('')

const WEEKDAYS = ['Sen', 'Sel', 'Rab', 'Kam', 'Jum', 'Sab', 'Min']
const MONTHS = [
	'Januari',
	'Februari',
	'Maret',
	'April',
	'Mei',
	'Juni',
	'Juli',
	'Agustus',
	'September',
	'Oktober',
	'November',
	'Desember',
]

function ymd(d) {
	const m = String(d.getMonth() + 1).padStart(2, '0')
	const day = String(d.getDate()).padStart(2, '0')
	return `${d.getFullYear()}-${m}-${day}`
}
function parseYmd(s) {
	const [y, m, d] = String(s).split('-').map(Number)
	return new Date(y, (m || 1) - 1, d || 1)
}

const dateSummary = computed(() => {
	const a = filterDraft.tanggal_dari
	const b = filterDraft.tanggal_sampai
	if (a && b) return `${formatDate(a)} – ${formatDate(b)}`
	if (a) return `Dari ${formatDate(a)}`
	if (b) return `Sampai ${formatDate(b)}`
	return ''
})

function openDateSheet() {
	rangeStart.value = filterDraft.tanggal_dari
	rangeEnd.value = filterDraft.tanggal_sampai
	const base = filterDraft.tanggal_dari || ymd(new Date())
	const d = parseYmd(base)
	calCursor.value = new Date(d.getFullYear(), d.getMonth(), 1)
	showDateSheet.value = true
}

const calLabel = computed(
	() => `${MONTHS[calCursor.value.getMonth()]} ${calCursor.value.getFullYear()}`
)
const calDays = computed(() => {
	const year = calCursor.value.getFullYear()
	const month = calCursor.value.getMonth()
	const first = new Date(year, month, 1)
	const startOffset = (first.getDay() + 6) % 7
	const daysInMonth = new Date(year, month + 1, 0).getDate()
	const cells = []
	for (let i = 0; i < startOffset; i++) cells.push(null)
	for (let d = 1; d <= daysInMonth; d++) cells.push(new Date(year, month, d))
	return cells
})
function prevMonth() {
	calCursor.value = new Date(calCursor.value.getFullYear(), calCursor.value.getMonth() - 1, 1)
}
function nextMonth() {
	calCursor.value = new Date(calCursor.value.getFullYear(), calCursor.value.getMonth() + 1, 1)
}
function pickDay(date) {
	const s = ymd(date)
	if (!rangeStart.value || (rangeStart.value && rangeEnd.value)) {
		rangeStart.value = s
		rangeEnd.value = ''
	} else if (s < rangeStart.value) {
		rangeEnd.value = rangeStart.value
		rangeStart.value = s
	} else {
		rangeEnd.value = s
	}
}
function dayClass(date) {
	const s = ymd(date)
	const isStart = s === rangeStart.value
	const isEnd = s === rangeEnd.value
	if (isStart || isEnd) return 'rounded-full bg-primary font-semibold text-ui-onPrimary'
	if (rangeStart.value && rangeEnd.value && s > rangeStart.value && s < rangeEnd.value)
		return 'rounded-md bg-primary/10 text-primary'
	if (s === ymd(new Date())) return 'rounded-full font-semibold text-primary'
	return 'rounded-full text-ui-ink-gray-700 hover:bg-ui-surface-gray-100'
}
function clearDateRange() {
	rangeStart.value = ''
	rangeEnd.value = ''
}
function applyDateRange() {
	filterDraft.tanggal_dari = rangeStart.value
	filterDraft.tanggal_sampai = rangeEnd.value
	showDateSheet.value = false
}

// ---- Fetch ----------------------------------------------------------------
function buildFilters() {
	const arr = []
	const f = appliedFilter
	if (f.name.trim()) arr.push(['name', 'like', `%${f.name.trim()}%`])
	if (jenisTerkunci.value) arr.push(['jenis_dokumen', '=', jenisTerkunci.value])
	else if (f.jenis.length) arr.push(['jenis_dokumen', 'in', [...f.jenis]])
	if (f.status.length) arr.push(['status', 'in', [...f.status]])
	if (f.tanggal_dari && f.tanggal_sampai)
		arr.push(['tanggal', 'between', [f.tanggal_dari, f.tanggal_sampai]])
	else if (f.tanggal_dari) arr.push(['tanggal', '>=', f.tanggal_dari])
	else if (f.tanggal_sampai) arr.push(['tanggal', '<=', f.tanggal_sampai])
	return arr
}

const list = createResource({
	url: 'frappe.client.get_list',
	makeParams() {
		const params = {
			doctype: 'Request Dokumen Collection',
			fields: JSON.stringify(FIELDS),
			order_by: `${sortField.value} ${sortDir.value}`,
			limit_start: start.value,
			limit_page_length: PAGE_LENGTH,
		}
		const andF = buildFilters()
		if (andF.length) params.filters = JSON.stringify(andF)
		return params
	},
	auto: false,
	onSuccess(data) {
		const batch = data || []
		rows.value = start.value === 0 ? batch : rows.value.concat(batch)
		hasMore.value = batch.length === PAGE_LENGTH
		loading.value = false
	},
	onError(err) {
		error.value = err?.message || String(err)
		loading.value = false
	},
})

function reload() {
	start.value = 0
	error.value = ''
	loading.value = true
	list.fetch()
}
function loadMore() {
	start.value += PAGE_LENGTH
	loading.value = true
	list.fetch()
}

function formatDate(v) {
	const d = new Date(String(v).replace(' ', 'T'))
	if (Number.isNaN(d.getTime())) return String(v)
	return d.toLocaleDateString('id-ID', { day: '2-digit', month: 'short', year: 'numeric' })
}

onMounted(() => {
	loadMyRoles()
	const saved = listPersistence.readSession({ filters: blankFilter() }).filters
	saved.jenis = saved.jenis.filter((value) => JENIS_LIST.includes(value))
	saved.status = saved.status.filter((value) => STATUS_LIST.includes(value))
	Object.assign(appliedFilter, saved)
	const prefs = listPersistence.readPreferences({ sortField: 'modified', sortDir: 'desc' })
	if (SORT_FIELDS.some((field) => field.key === prefs.sortField))
		sortField.value = prefs.sortField
	if (['asc', 'desc'].includes(prefs.sortDir)) sortDir.value = prefs.sortDir
	reload()
})
</script>

<style>
/* Field baris pada bottom-sheet Filter — sama dengan Data Pengajuan / STPL. */
.dp-field {
	@apply flex w-full items-center gap-3 rounded-2xl border border-ui-line-gray-300 px-4 py-3.5 transition;
}
.dp-field-input {
	@apply w-full border-0 bg-transparent p-0 text-ui-ink-gray-800 placeholder-ui-ink-gray-500 caret-primary outline-none focus:ring-0;
}
.dp-field-ic {
	@apply h-5 w-5 shrink-0 text-ui-ink-gray-500;
}
.dp-field-chev {
	@apply h-4 w-4 shrink-0 text-ui-ink-gray-500;
}
</style>
